The index, 2016–2026

wfuStatus = (await fetch("data/status.json")).json()
wfuFreqs = wfuStatus.daily ? ["Daily", "Weekly", "Monthly", "Quarterly", "Annual"] : ["Monthly", "Quarterly", "Annual"]

















viewof wfuFreq = Inputs.radio(wfuFreqs, {value: wfuFreqs[0], label: "Frequency"})
viewof wfuSpan = Inputs.select(["2016 – today", "Since 2020", "Since 2024"], {label: "Period"})

















wfuEvents = [
  {date: "2016-06-23", label: "Brexit referendum", row: 0},
  {date: "2016-11-08", label: "US election", row: 1},
  {date: "2019-01-01", label: "US gov't shutdown", row: 2},
  {date: "2019-08-05", label: "US–China trade war", row: 1},
  {date: "2020-03-27", label: "COVID-19 fiscal packages", row: 0},
  {date: "2020-11-03", label: "US election", row: 1},
  {date: "2022-09-23", label: "UK mini-budget", row: 1},
  {date: "2023-05-15", label: "US debt ceiling", row: 0},
  {date: "2024-12-04", label: "France budget crisis", row: 1},
  {date: "2025-04-02", label: "US tariff shock", row: 0},
  {date: "2025-07-04", label: "US budget law (OBBBA)", row: 2},
  {date: "2025-10-01", label: "US gov't shutdown", row: 3}
].map(d =&gt; ({...d, date: new Date(d.date)}))

wfuData = {
  const f = wfuFreq.toLowerCase();
  const rows = await d3.csv(`data/plot/world_${f}.csv`, d3.autoType);
  const when = d =&gt;
    f === "daily" ? new Date(d.DATE) :
    f === "weekly" ? new Date(d.WEEK_START) :
    f === "monthly" ? new Date(Date.UTC(d.YEAR, d.MONTH - 1, 15)) :
    f === "quarterly" ? new Date(Date.UTC(d.YEAR, 3 * d.QUARTER - 2, 15)) :
    new Date(Date.UTC(d.YEAR, 6, 1));
  const lab = d =&gt;
    f === "daily" ? d3.utcFormat("%-d %b %Y")(when(d)) :
    f === "weekly" ? `Week of ${d3.utcFormat("%-d %b %Y")(when(d))}` :
    f === "monthly" ? d3.utcFormat("%b %Y")(when(d)) :
    f === "quarterly" ? `${d.YEAR} Q${d.QUARTER}` : `${d.YEAR}${d.PARTIAL ? " (Jan–Sep)" : ""}`;
  return rows.map(d =&gt; ({...d, date: when(d), when: lab(d)}));
}

wfuChart = {
  const start = {"2016 – today": "2015-12-01", "Since 2020": "2020-01-01", "Since 2024": "2024-01-01"}[wfuSpan];
  const x0 = new Date(start), x1 = new Date("2026-10-31");
  const rows = wfuData.filter(d =&gt; d.date &gt;= x0);
  const daily = wfuFreq === "Daily";
  const smooth = daily ? Plot.windowY({k: 30, anchor: "middle"}, {x: "date", y: "WFU"}) : {x: "date", y: "WFU"};
  const ymax = d3.max(rows, d =&gt; d.WFU) * (daily ? 1.15 : 1.3);
  const ev = wfuEvents.filter(d =&gt; d.date &gt;= x0);
  return Plot.plot({
    width, height: 440, marginLeft: 48, marginTop: 10,
    x: {type: "utc", domain: [x0, x1], label: null},
    y: {domain: [0, ymax], grid: true, label: "Index, 2016–2025 average = 100", clamp: true},
    marks: [
      Plot.ruleY([100], {stroke: "currentColor", strokeOpacity: 0.4, strokeDasharray: "4,3"}),
      Plot.ruleX(ev, {x: "date", stroke: "currentColor", strokeOpacity: 0.18}),
      Plot.text(ev, {x: "date", y: d =&gt; ymax * (0.98 - 0.075 * d.row), text: "label", fontSize: 10.5,
                     fill: "currentColor", fillOpacity: 0.75, lineWidth: 7, lineAnchor: "top", textAnchor: "middle"}),
      daily ? Plot.lineY(rows, {x: "date", y: "WFU", stroke: "#9ec5f4", strokeWidth: 0.7}) : null,
      Plot.lineY(rows, {...smooth, stroke: "#2a78d6", strokeWidth: 2}),
      Plot.tip(rows, Plot.pointerX({x: "date", y: "WFU", title: d =&gt;
        `${d.when}\nWFU ${d.WFU?.toFixed(1)}  (z = ${d.WFU_Z?.toFixed(2)})\nWEPU ${d.WEPU?.toFixed(1)}\n${d3.format(",")(d.N_W)} articles`}))
    ]
  });
}























Figure 1 (interactive). World Fiscal Uncertainty index (WFU), 2016–2025 average = 100 (dashed line). At daily frequency the light line is the daily index and the dark line its 30-day centred moving average. Values are shown on pointing at the figure. Data end on 30 September 2026.

For each economy the indices are computed from three sets of articles: those published by outlets located in the economy (domestic index, DFU), those published by outlets located elsewhere that mention the economy (foreign index, XFU), and all articles that mention the economy (all-sources index, AFU). The domestic index is the counterpart of a national newspaper index; the foreign index measures the external narrative about the economy’s public finances. Each index equals 100 on average over 2016–2025 within its economy, so that it describes movements over time rather than differences in level across economies. Cross-country comparisons of levels should use the shares (_SH) or the standardized series (_Z) in the data files.

cM = d3.csv("data/plot/country_monthly.csv", d3.autoType)
cA = d3.csv("data/plot/country_annual.csv", d3.autoType)
cNames = d3.sort(Array.from(d3.rollup(cA, v =&gt; v[0].COUNTRY, d =&gt; d.ISO3), ([iso, name]) =&gt; ({iso, name})), d =&gt; d.name)
























viewof cIso = Inputs.select(new Map(cNames.map(d =&gt; [`${d.name} (${d.iso})`, d.iso])), {value: "USA", label: "Economy"})
viewof cFreq = Inputs.radio(["Monthly", "Annual"], {value: "Monthly", label: "Frequency"})
viewof cSeries = Inputs.checkbox(cKeys, {value: cKeys.slice(0, 2), label: "Series"})
viewof cLog = Inputs.toggle({label: "Logarithmic scale", value: true})































cKeys = ["Domestic press (DFU)", "Foreign press (XFU)", "All sources (AFU)", "Domestic, stable outlets (DFU_PNL)"]
cCols = ({"Domestic press (DFU)": "DFU", "Foreign press (XFU)": "XFU", "All sources (AFU)": "AFU",
          "Domestic, stable outlets (DFU_PNL)": "DFU_PNL"})
cRows = {
  const src = (cFreq === "Monthly" ? cM : cA).filter(d =&gt; d.ISO3 === cIso);
  const date = d =&gt; cFreq === "Monthly" ? new Date(Date.UTC(d.YEAR, d.MONTH - 1, 15)) : new Date(Date.UTC(d.YEAR, 6, 1));
  const when = d =&gt; cFreq === "Monthly" ? d3.utcFormat("%b %Y")(date(d)) : `${d.YEAR}${d.YEAR === 2026 ? " (Jan–Sep)" : ""}`;
  return cSeries.flatMap(s =&gt; src.map(d =&gt; ({date: date(d), when: when(d), series: s, value: d[cCols[s]],
                                            thin: d.THIN_D === 1, n: d.N_D})))
                .filter(d =&gt; d.value != null && d.value &gt; 0);
}
cChart = Plot.plot({
  width, height: 420, marginLeft: 50,
  x: {type: "utc", label: null},
  y: cLog
    ? {type: "log", grid: true, label: "Index, 2016–2025 average = 100 (log scale)",
       domain: [Math.min(50, d3.min(cRows, d =&gt; d.value)) * 0.9, Math.max(200, d3.max(cRows, d =&gt; d.value)) * 1.1],
       ticks: [10, 25, 50, 100, 200, 400, 800, 1600], tickFormat: d3.format(",")}
    : {grid: true, zero: true, label: "Index, 2016–2025 average = 100"},
  color: {domain: cKeys, range: ["#2a78d6", "#eb6834", "#1baf7a", "#6250d6"], legend: true},
  marks: [
    Plot.ruleY([100], {stroke: "currentColor", strokeOpacity: 0.4, strokeDasharray: "4,3"}),
    Plot.lineY(cRows, {x: "date", y: "value", stroke: "series", strokeWidth: 2}),
    cFreq === "Annual" ? Plot.dot(cRows, {x: "date", y: "value", fill: "series", r: 4, stroke: "var(--bs-body-bg, white)", strokeWidth: 1.5}) : null,
    Plot.tip(cRows, Plot.pointerX({x: "date", y: "value", stroke: "series", title: d =&gt;
      `${d.when}\n${d.series}: ${d.value.toFixed(1)}${d.thin ? "\n(thin domestic cell: few articles)" : ""}`}))
  ]
})






























Figure 1 (interactive). Fiscal policy uncertainty indices for the selected economy, calendar basis. Cells with fewer than 1,000 domestic articles or 10 fiscal uncertainty articles in a month (2,000 and 20 in a year) are noisy even after shrinkage and are flagged in the data (THIN_D, THIN_X, THIN_A). Where the composition of news outlets changes markedly, the stable-outlet series DFU_PNL is preferable (flag COMPBRK_D).

